package mod.cdv.tnpc.tactical;import java.util.*;import dev.zomboid.corpse.NpcCorpse20;public class CorpseAppearance20Checks{static int n;static void ok(boolean v,String m){n++;if(!v)throw new AssertionError(m);}public record Profile(UUID id,String name){public UUID getId(){return id;}public String getName(){return name;}}public record Dummy(Profile profile){public Profile getGameProfile(){return profile;}}public static void main(String[]a)throws Exception{fixture.World w=new fixture.World();for(int i=0;i<24;i++){var actor=new mod.cdv.tnpc.entity.AutoGunOperator(w);actor.uuid=UUID.nameUUIDFromBytes(("corpse"+i).getBytes());Social.init(actor);var result=(net.minecraft.client.resources.PlayerSkin)NpcCorpse20.skin(new Dummy(new Profile(actor.uuid,Identity20.name(actor))));String expected=String.format(java.util.Locale.ROOT,"survivor_%02d.png",actor.tag.getInt("soc_skin20"));ok(result.texture().toString().endsWith(expected),"dead NPC keeps same masculine/feminine appearance");}ok(NpcCorpse20.skin(new Dummy(new Profile(UUID.randomUUID(),"PlayerName")))==null,"normal player corpse skin remains vanilla");var corpse=new de.maxhenkel.corpse.entities.CorpseEntity(w);var player=new net.minecraft.server.level.ServerPlayer(w);ok(NpcCorpse20.interact(corpse,player,null)==null,"normal player corpse access rules unchanged");corpse.tag.putBoolean("soc_npc_corpse20",true);ok(NpcCorpse20.interact(corpse,player,null)!=null&&de.maxhenkel.corpse.gui.Guis.opened==1,"NPC corpse remains lootable even with owner-only player corpse rules");System.out.println("NPC_CORPSE_SKIN_AND_ACCESS_CHECKS="+n);}}